function roomAllowed(room,b){if(kind==='presentations'||kind==='activities')return false; if(day!=='all'&&room.days&&!room.days.includes(day))return false;const local=blockQueries[b]||'';return (!query||searchText(room).includes(query)||norm(blockNames[b]).includes(query))&&(!local||searchText(room).includes(local))}
