 if(entries.length){entries.sort((a,z)=>{const aP=(a.room.title.match(/^(\d+)/)||[])[1],bP=(z.room.title.match(/^(\d+)/)||[])[1];return aP&&bP?Number(aP)-Number(bP):aP?-1:bP?1:a.room.title.localeCompare(z.room.title,'pt-BR')});for(const {room,es} of entries){content.append(roomCard(room,es,true));visibleCount+=es.length+1}}
