function apply(){
 const vp=$('viewport'),stage=$('stage'),width=vp.clientWidth,height=vp.clientHeight;
 // Fit the original aspect ratio even when fullscreen is taller or wider than the map.
 const fit=Math.min(width/mapBounds.width,height/mapBounds.height);
 const mapWidth=mapBounds.width*fit*zoom,mapHeight=mapBounds.height*fit*zoom;
 const mx=Math.max(0,(mapWidth-width)/2),my=Math.max(0,(mapHeight-height)/2);
 panX=Math.min(mx,Math.max(-mx,panX));panY=Math.min(my,Math.max(-my,panY));
 // Resize the actual image/SVG layout, avoiding an upscaled compositor bitmap on phones.
 stage.style.width=mapWidth+'px';stage.style.height=mapHeight+'px';
 stage.style.left=(width-mapWidth)/2+panX+'px';
 stage.style.top=(height-mapHeight)/2+panY+'px';
}
function scale(v,point){
 const next=Math.max(1,Math.min(4,v));
 if(point){panX=point.x-(point.x-panX)*next/zoom;panY=point.y-(point.y-panY)*next/zoom}
 zoom=next;apply();
}
function reset(){zoom=1;panX=panY=0;apply()}
