const vp=$('viewport'),pointers=new Map();
let pinch=null;
function localPoint(x,y){
 const r=vp.getBoundingClientRect();
 return {x:x-r.left-vp.clientLeft-vp.clientWidth/2,y:y-r.top-vp.clientTop-vp.clientHeight/2};
}
function gesture(){
 const [a,b]=[...pointers.values()];
 return {center:localPoint((a.x+b.x)/2,(a.y+b.y)/2),distance:Math.max(1,Math.hypot(a.x-b.x,a.y-b.y))};
}
vp.addEventListener('wheel',e=>{
 e.preventDefault();scale(zoom*(e.deltaY<0?1.12:1/1.12),localPoint(e.clientX,e.clientY));
},{passive:false});
vp.addEventListener('pointerdown',e=>{
 if(e.button!==0)return;
 pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
 if(pointers.size===1){drag={id:e.pointerId,x:e.clientX,y:e.clientY,px:panX,py:panY};moved=false}
 if(pointers.size===2){
  pinch={...gesture(),zoom,px:panX,py:panY};drag=null;moved=true;
  for(const id of pointers.keys())vp.setPointerCapture(id);
 }
});
vp.addEventListener('pointermove',e=>{
 if(!pointers.has(e.pointerId))return;
 pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
 if(pinch&&pointers.size>=2){
  const g=gesture(),next=Math.max(1,Math.min(4,pinch.zoom*g.distance/pinch.distance)),ratio=next/pinch.zoom;
  panX=g.center.x-(pinch.center.x-pinch.px)*ratio;
  panY=g.center.y-(pinch.center.y-pinch.py)*ratio;
  zoom=next;moved=true;apply();return;
 }
 if(!drag||drag.id!==e.pointerId)return;
 const dx=e.clientX-drag.x,dy=e.clientY-drag.y;
 if(Math.hypot(dx,dy)>5)moved=true;
 if(moved){
  if(!vp.hasPointerCapture(e.pointerId))vp.setPointerCapture(e.pointerId);
  panX=drag.px+dx;panY=drag.py+dy;apply();vp.classList.add('panning');
 }
});
function end(e){
 if(!pointers.delete(e.pointerId))return;
 pinch=null;drag=null;
 if(pointers.size===1){
  const [id,p]=[...pointers.entries()][0];
  drag={id,x:p.x,y:p.y,px:panX,py:panY};
 }
 if(!pointers.size){vp.classList.remove('panning');setTimeout(()=>{moved=false},0)}
}
vp.addEventListener('pointerup',end);vp.addEventListener('pointercancel',end);
vp.addEventListener('lostpointercapture',end);
window.addEventListener('pointerup',end);window.addEventListener('resize',apply);
new ResizeObserver(apply).observe(vp);
